    n=len(grid); H=W=n
    out=[row[:] for row in grid]
    vals=Counter(v for row in grid for v in row)
    N=max(vals); 
    def cyc(v,k): # next value after v (cyclic mod N, 1..N)
        if k=='next': return (v-1)%N+1
        if k=='prev': return (v+1)%N+1
    def pred(v,k): return cyc(v,k)
    changed=True
