                if j<W-1: cands.append(pred(out[i][j+1],'prev'))
                if i>0: cands.append(pred(out[i-1][j],'next'))
                if i<H-1: cands.append(pred(out[i+1][j],'prev'))
                if not cands: continue
                cnt=Counter(cands)
                best,cntv=cnt.most_common(1)[0]
                if len(cnt)>1:
                    ties=sorted(cnt.items())
                    if len(ties)>1 and ties[0][1]>ties[1][1]:
                        pass
                    elif len(ties)>1:
