def g(I, mode='nxt'):
    H,W=len(I),len(I[0])
    vals=sorted({v for r in I for v in r})
    m=max(vals)
    if mode=='nxt':
        def nxt(v): return v+1 if v<m else 1
    elif mode=='wrap2m1':
        def nxt(v): return (v%23)+1
    else:
        return None
    o=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=0: continue
            up=o[r-1][c] if r>0 else None
            lf=o[r][c-1] if c>0 else None
            diag=None
            if r>0 and c>0:
                d=I[r-1][c-1]
                dd=o[r-1][c-1]
                diag=(dd!=0)
            # priority: above first
            if up is not None and up!=0:
                o[r][c]=nxt(up)
            elif diag and (up is None or up==0):
                o[r][c]=nxt(dd) if dd!=0 else 1
            elif lf is not None and lf!=0:
                o[r][c]=nxt(lf)
            else:
                # nothing found: cycle back to start of the pattern? try: find any nonzero anywhere and +1
                seen={v for r_ in I for v in r_}
                o[r][c]=min(seen|{1}, key=lambda v:(abs(nxt(v)-min(o[r]))))
    return o
