# Rule: for each zero, take nearest nonzero in same column (vertical) OR same row (horizontal), whichever closer.
def f(I):
    H,W=I.shape; out=I.copy()
    for r in range(H):
        for c in range(W):
            if I[r,c]!=0: continue
            up=[i for i in range(r) if I[i,c]!=0]; dn=[i for i in range(r+1,H) if I[i,c]!=0]
            lt=[j for j in range(c) if I[r,j]!=0]; rt=[j for j in range(c+1,W) if I[r,j]!=0]
            cand=[]
            if up: cand.append((abs(r-max(up)),int(I[max(up),c]),'u'))
            if dn: cand.append((min(dn)-r,int(I[min(dn),c]),'d'))
            if lt: cand.append((c-max(lt),int(I[r,max(lt)]),'l'))
            if rt: cand.append((min(rt)-c,int(I[r,min(rt)]),'r'))
            best=min(cand,key=lambda x:(x[0],x[2]))
            out[r,c]=best[1]
    return out
print('demo match:',np.array_equal(f(I),O))
print(np.argwhere(f(I)!=O)[:20])

